export function createMysticSfx(music){const seen=new Set();return{accept(events){for(const e of events){if(!e.type?.startsWith('mystic')||!e.id||seen.has(e.id))continue;if(seen.size>=96)seen.delete(seen.values().next().value);seen.add(e.id);const t=music.ctx?.currentTime||0,tone=(f,d,v=.04,delay=0,to=f)=>music.tone(f,d,'sine',v,t+delay,to,.006,true);if(e.type==='mysticClue'){tone(660,.08);tone(990,.13,.03,.055);}else if(e.type==='mysticSwap'){tone(360,.28,.05,0,780);tone(540,.2,.025,.09,1080);}else if(e.type==='mysticInterrupt'){tone(660,.13,.065);tone(990,.2,.045,.08);tone(1320,.3,.035,.16);}else if(e.type==='mysticFalse')tone(330,.18,.045,0,140);else if(e.type==='mysticAim')tone(220,.1,.035,0,330);else if(e.type==='mysticShot'){tone(180,.17,.065,0,60);tone(720,.07,.035,0,180);}else if(e.type==='mysticShatter'){music.bossImpactAudio?.consume([{type:'rockfall'}]);tone(120,.3,.1,0,48);for(let i=0;i<5;i++)tone(500+i*180,.08,.035,.03*i,120);}else if(e.type==='mysticExhausted'){tone(340,.24,.045,0,190);tone(220,.25,.03,.1,140);}else if(e.type==='mysticTrail')tone(180,.1,.025,0,100);else if(e.type==='mysticAppear')tone(440,.2,.035,0,660);}},reset(){seen.clear();}};}
